    "Fix compileExpr(): its string-replacement calls insert the literal text '// @FIGURE_CODE_BEGIN1*x' / '// @FIGURE_CODE_BEGIN*x' where a regex backreference like '$11*x' / '$1*x' was clearly intended. The stray '//' starts a comment that truncates the generated Function body, so compileExpr throws on every call and evaluateGeometry silently falls back to the hardcoded default triangle — the equation inputs currently have zero visible effect on the drawn shape.",
    "Change RIGHT_FILL from the pale tan (#fde8b8) to an actual yellow so R1/R2 read as the blue/yellow split the source uses.",
    "Merge the two duplicate 'y = 3' labels into a single label for the shared top boundary."
  ],
  "plan_action_items": []
}

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Outer polar boundary r = <input id="outerRInput" value="2*(1+cos(theta))" style="width:170px"></label><label>Ray angle θ: <output id="thetaSweepVal">π/4</output><input id="thetaSweepInput" type="range" min="0" max="1.5707963267948966" step="0.01" value="0.7853981633974483" oninput="document.getElementById('thetaSweepVal').value=this.value;update_thetaSweep(+this.value)"></label><span id="sliceReadout" style="font-size:10px;line-height:1.25"></span><span id="demoNarration" style="display:inline-block;margin:0;font-size:10px;max-width:260px;line-height:1.25"></span><span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var frame = setPlotFrame({
  xDomain: [-2.9, 4.6],
  yDomain: [-2.95, 3.15],
  margin: 26,
  draw: draw
});

var BLUE = '#2aa4dd';
var PURPLE = '#b65cad';
var FILL = '#c7e4ef';
var RED = '#f05a61';
var AXIS = '#222222';

var currentTheta = Math.PI / 4;
var outerSrc = '2*(1+cos(theta))';
var outerFn = function (theta) { return 2 * (1 + Math.cos(theta)); };
var currentStep = 0;

var demoSteps = [
  {
    title: 'Identify the boundaries',
    narration: 'The blue circle r = 2 is the inner boundary, and the purple cardioid is the outer boundary in the first quadrant. The shaded region is the part outside the circle but inside the cardioid.',
    state: { thetaSweep: Math.PI / 4 }
  },
  {
    title: 'Sweep a radial slice',
    narration: 'Move theta through the first quadrant. At each angle, the red radial segment starts when it hits the circle at r = 2 and ends when it hits the cardioid at r = 2(1 + cos theta).',
    state: { thetaSweep: Math.PI / 4 }
  },
  {
    title: 'Reach the intersection',
    narration: 'At theta = pi/2, the circle and cardioid meet, so the radial thickness of the region shrinks to zero. This fixes the upper angular limit.',
    state: { thetaSweep: Math.PI / 2 }
  }
];

function configureFrame() {
  var container = document.getElementById('container');
  frame.width = container.clientWidth || frame.width || 900;
  frame.height = container.clientHeight || frame.height || 600;

  var innerW = Math.max(10, frame.width - 2 * frame.margin);
  var innerH = Math.max(10, frame.height - 2 * frame.margin);
  var targetYLen = 6.1;
  var xLen = Math.max(7.55, targetYLen * innerW / innerH);
  var yLen = xLen * innerH / innerW;

  var xCenter = 0.85;
  var yCenter = 0.08;
  frame.xDomain = [xCenter - xLen / 2, xCenter + xLen / 2];
  frame.yDomain = [yCenter - yLen / 2, yCenter + yLen / 2];
  _recomputePlotScale();
}

function pointString(points) {
  return points.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' ');
}

function polarPoint(r, theta) {
  return [plotX(r * Math.cos(theta)), plotY(r * Math.sin(theta))];
}

function sampleCircle(n) {
  var pts = [];
  for (var i = 0; i <= n; i++) {
    var t = 2 * Math.PI * i / n;
    pts.push(polarPoint(2, t));
  }
  return pts;
}

function samplePolarSegments(fn, a, b, n) {
  var segs = [];
  var cur = [];
  for (var i = 0; i <= n; i++) {
    var t = a + (b - a) * i / n;
    var r;
    try { r = fn(t); } catch (e) { r = NaN; }
    if (isFinite(r) && Math.abs(r) < 1000) {
      cur.push(polarPoint(r, t));
    } else {
      if (cur.length > 1) segs.push(cur);
      cur = [];
    }
  }
  if (cur.length > 1) segs.push(cur);
  return segs;
}

function addMathText(parent, str, x, y, size, anchor) {
  return parent.text(str)
    .font({
      family: 'Georgia, "Times New Roman", serif',
      size: size,
      style: 'italic',
      anchor: anchor || 'middle'
    })
    .attr({
      x: x,
      y: y,
      fill: '#202020',
      'dominant-baseline': 'middle',
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': Math.max(3, size * 0.14),
      'stroke-linejoin': 'round'
    });
}

function mathText(str, x, y, size, anchor) {
  return addMathText(draw, str, x, y, size, anchor);
}

function thetaPiOver2Label(x, y, size) {
  var g = draw.group();
  addMathText(g, 'θ =', x - size * 0.36, y, size, 'end');
  addMathText(g, 'π', x + size * 0.12, y - size * 0.27, size * 0.92, 'middle');
  g.line(x - size * 0.18, y + size * 0.02, x + size * 0.44, y + size * 0.02)
    .stroke({ color: '#ffffff', width: Math.max(7, size * 0.2), linecap: 'round' });
  g.line(x - size * 0.18, y + size * 0.02, x + size * 0.44, y + size * 0.02)
    .stroke({ color: '#202020', width: Math.max(2, size * 0.055), linecap: 'round' });
  addMathText(g, '2', x + size * 0.12, y + size * 0.35, size * 0.92, 'middle');
  return g;
}

function formatTheta(v) {
  if (Math.abs(v) < 0.006) return '0';
  if (Math.abs(v - Math.PI / 2) < 0.006) return 'π/2';
  if (Math.abs(v - Math.PI / 4) < 0.02) return 'π/4';
  return v.toFixed(2);
}

function formatNum(v) {
  if (!isFinite(v)) return 'undefined';
  if (Math.abs(v) < 0.0005) return '0';
  return v.toFixed(2).replace(/\.00$/, '');
}

function updateReadout() {
  var out = document.getElementById('thetaSweepVal');
  if (out) out.value = formatTheta(currentTheta);

  var rOuter;
  try { rOuter = outerFn(currentTheta); } catch (e) { rOuter = NaN; }
  var readout = document.getElementById('sliceReadout');
  if (readout) {
    var interval = (isFinite(rOuter) && rOuter >= 2)
      ? ('2 ≤ r ≤ ' + formatNum(rOuter))
      : 'no outside-circle slice';
    readout.innerHTML =
      'At θ = ' + formatTheta(currentTheta) +
      ', slice: ' + interval +
      '<br>Integral limits: 0 ≤ θ ≤ π/2, 2 ≤ r ≤ 2(1 + cos θ)';
  }
}

function drawShadedRegion() {
  var top = [];
  var bottom = [];
  var started = false;
  var ok = true;

  for (var i = 0; i <= 160; i++) {
    var th = (Math.PI / 2) * i / 160;
    var r;
    try { r = outerFn(th); } catch (e) { r = NaN; }
    if (isFinite(r) && r >= 2 && Math.abs(r) < 1000) {
      top.push(polarPoint(r, th));
      bottom.push(polarPoint(2, th));
      started = true;
    } else if (started) {
      ok = false;
    }
  }

  if (top.length < 2) return;
  bottom.reverse();
  var shaded = draw.polygon(pointString(top.concat(bottom)))
    .fill({ color: FILL, opacity: 0.9 })
    .stroke('none');
  shaded.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Region R: outside r = 2 and inside the cardioid for 0 ≤ θ ≤ π/2.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Polar region R', 'The shaded set is built ray by ray. For each angle in the first quadrant, r starts at the circle r = 2 and ends at the outer curve r = 2(1 + cos θ).');
    });
}

function render() {
  configureFrame();
  draw.clear();

  var x0 = frame.xDomain[0], x1 = frame.xDomain[1];
  var y0 = frame.yDomain[0], y1 = frame.yDomain[1];

  draw.line(plotX(x0), plotY(0), plotX(x1), plotY(0))
    .stroke({ color: AXIS, width: 3, linecap: 'square' });
  draw.line(plotX(0), plotY(y0), plotX(0), plotY(y1))
    .stroke({ color: AXIS, width: 3, linecap: 'square' });

  drawShadedRegion();

  var circle = draw.polyline(pointString(sampleCircle(280)))
    .fill('none')
    .stroke({ color: BLUE, width: 6, linecap: 'round', linejoin: 'round' });
  circle.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Inner boundary: r = 2.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Inner boundary', 'The circle r = 2 is the lower radial limit. Every red radial slice begins at this circle.');
    });

  var cardioidSegments = samplePolarSegments(outerFn, 0, 2 * Math.PI, 560);
  for (var s = 0; s < cardioidSegments.length; s++) {
    var card = draw.polyline(pointString(cardioidSegments[s]))
      .fill('none')
      .stroke({ color: PURPLE, width: 6, linecap: 'round', linejoin: 'round' });
    card.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Outer boundary: r = ' + outerSrc, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Outer boundary', 'The purple curve supplies the upper radial limit. Editing the formula changes where each radial slice stops.');
      });
  }

  var rOuterNow;
  try { rOuterNow = outerFn(currentTheta); } catch (e) { rOuterNow = NaN; }
  if (isFinite(rOuterNow) && rOuterNow > 2.005) {
    var pInner = polarPoint(2, currentTheta);
    var pOuter = polarPoint(rOuterNow, currentTheta);
    draw.line(pInner[0], pInner[1], pOuter[0], pOuter[1])
      .stroke({ color: RED, width: 5, linecap: 'round' })
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Radial slice: 2 ≤ r ≤ outer boundary at this θ.', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Radial slice', 'This red segment is not a full ray. It is exactly the interval of r-values used in the polar integral for the selected angle θ.');
      });
  }

  draw.circle(24).center(plotX(0), plotY(0)).fill({ color: '#000000', opacity: 0.001 }).stroke('none')
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Origin: polar rays start here.', e); })
    .on('mouseleave', hideTooltip);

  draw.circle(26).center(plotX(0), plotY(2)).fill({ color: '#000000', opacity: 0.001 }).stroke('none')
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Intersection at θ = π/2: both boundaries have r = 2.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Upper angle limit', 'At θ = π/2, the cardioid gives r = 2(1 + cos(π/2)) = 2. The inner and outer limits match, so the region ends there.');
    });

  draw.circle(26).center(plotX(4), plotY(0)).fill({ color: '#000000', opacity: 0.001 }).stroke('none')
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Rightmost cardioid point: θ = 0 gives r = 4.', e); })
    .on('mouseleave', hideTooltip);

  thetaPiOver2Label(plotX(-0.78), plotY(2.78), 36);
  mathText('r = 2(1 + cos θ)', plotX(2.55), plotY(2.92), 34, 'middle');
  mathText('r = 2', plotX(-2.42), plotY(1.42), 34, 'middle');
  mathText('θ = 0', plotX(2.95), plotY(-0.43), 36, 'middle');

  updateReadout();
}

function update_thetaSweep(v) {
  currentTheta = Math.max(0, Math.min(Math.PI / 2, v));
  var input = document.getElementById('thetaSweepInput');
  if (input && Math.abs(+input.value - currentTheta) > 1e-9) input.value = currentTheta;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];

  if (step.state && step.state.thetaSweep != null) {
    var slider = document.getElementById('thetaSweepInput');
    if (slider) slider.value = step.state.thetaSweep;
    update_thetaSweep(+step.state.thetaSweep);
  } else {
    render();
  }

  var narr = document.getElementById('demoNarration');
  if (narr) narr.textContent = step.narration;
  var label = document.getElementById('stepLabel');
  if (label) label.textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

bindEquationInput('outerRInput', function (fn, src) {
  outerFn = fn;
  outerSrc = src;
  render();
}, { variables: ['theta'] });

document.addEventListener('fig-resize', function () {
  render();
});

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
